def guardar_clientes(apps, schema_editor):
    """Los clientes de las facturas personalizadas ya emitidas quedan guardados (con sus datos más recientes)."""
    Factura = apps.get_model("caja", "Factura")
    ClienteFiscal = apps.get_model("caja", "ClienteFiscal")
    vistos = set()
    for f in Factura.objects.exclude(cliente_documento="").order_by("-emitida_en"):
        if f.cliente_documento in vistos:
            continue
        vistos.add(f.cliente_documento)
        ClienteFiscal.objects.create(
            documento=f.cliente_documento, nombre=f.cliente_nombre, direccion=f.cliente_direccion,
            telefono=f.cliente_telefono, correo=f.cliente_correo,
        )



